/**
 * Stale-while-revalidate cache for client data fetching.
 *
 * Freshness model per entry (age = now - fetchedAt):
 *   age < maxAge                                  -> fresh:   return cached data, no fetch
 *   maxAge <= age <= maxAge + staleWhileRevalidate -> stale:   return cached data immediately
 *                                                              AND fire one background revalidation
 *   age > maxAge + staleWhileRevalidate (or miss)  -> expired: fetch and await
 *
 * All fetches per key are single-flight: concurrent gets share one promise.
 */

export function createCache(fetcher, { maxAge, staleWhileRevalidate }) {
  if (typeof fetcher !== 'function') {
    throw new TypeError('fetcher must be a function');
  }
  if (!(Number.isFinite(maxAge) && maxAge >= 0)) {
    throw new TypeError('maxAge must be a non-negative finite number');
  }
  if (!(Number.isFinite(staleWhileRevalidate) && staleWhileRevalidate >= 0)) {
    throw new TypeError('staleWhileRevalidate must be a non-negative finite number');
  }

  /** key -> { data, fetchedAt } */
  const entries = new Map();
  /** key -> in-flight fetch promise (single-flight dedupe) */
  const inflight = new Map();

  /**
   * Start (or join) the single in-flight fetch for `key`.
   * On success the entry is refreshed with the new data and timestamp.
   * On failure the in-flight slot is released and any cached value is left untouched;
   * the rejection is marked handled so background use never triggers an
   * unhandled rejection, while awaiting callers still observe it.
   */
  function startFetch(key) {
    const existing = inflight.get(key);
    if (existing) return existing;

    const p = Promise.resolve()
      .then(() => fetcher(key))
      .then((data) => {
        entries.set(key, { data, fetchedAt: Date.now() });
        return data;
      });

    inflight.set(key, p);

    const release = () => {
      if (inflight.get(key) === p) inflight.delete(key);
    };
    // Attach cleanup as both fulfillment and rejection handler so the derived
    // promise here always resolves; also mark p itself handled for the
    // fire-and-forget (background revalidation) case.
    p.then(release, release);
    p.catch(() => {});

    return p;
  }

  async function get(key) {
    const entry = entries.get(key);

    if (!entry) {
      // Miss: fetch and await.
      return startFetch(key);
    }

    const age = Date.now() - entry.fetchedAt;

    if (age < maxAge) {
      // Fresh: serve from cache, no fetch.
      return entry.data;
    }

    if (age <= maxAge + staleWhileRevalidate) {
      // Stale: serve cached data immediately, revalidate exactly once in the
      // background (startFetch dedupes if a revalidation is already running).
      startFetch(key);
      return entry.data;
    }

    // Expired: fetch and await.
    return startFetch(key);
  }

  function peek(key) {
    return entries.get(key)?.data;
  }

  function invalidate(key) {
    entries.delete(key);
  }

  return { get, peek, invalidate };
}

