import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { createCache } from '../src/cache.js';

const MAX_AGE = 1000;
const SWR = 500;

/**
 * Mock fetcher that counts calls per key. Default payload for a key embeds the
 * per-key call ordinal so tests can observe refreshes; per-key impl overrides
 * (functions) let tests inject resolutions/rejections.
 */
function makeFetcher(impl = {}) {
  const calls = [];
  const fn = vi.fn(async (key) => {
    calls.push(key);
    if (Object.prototype.hasOwnProperty.call(impl, key)) {
      return impl[key](calls.filter((c) => c === key).length);
    }
    return `${key}:v${calls.filter((c) => c === key).length}`;
  });
  fn.callsTo = (key) => calls.filter((c) => c === key).length;
  return fn;
}

/** Drain pending microtasks without advancing the fake clock. */
async function flushMicrotasks() {
  for (let i = 0; i < 10; i++) await Promise.resolve();
}

describe('createCache (fake timers)', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('miss: fetches and awaits, caching the result', async () => {
    const fetcher = makeFetcher();
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    const data = await cache.get('a');
    expect(data).toBe('a:v1');
    expect(fetcher.callsTo('a')).toBe(1);
    expect(cache.peek('a')).toBe('a:v1');
  });

  it('fresh window: age under maxAge returns cached data with no fetch', async () => {
    const fetcher = makeFetcher();
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    await cache.get('a'); // populate at t=0
    vi.advanceTimersByTime(MAX_AGE - 1); // t=999: still fresh

    const data = await cache.get('a');
    expect(data).toBe('a:v1');
    expect(fetcher.callsTo('a')).toBe(1); // no fetch fired
  });

  it('stale window: returns cached data immediately AND fires exactly one background revalidation', async () => {
    const fetcher = makeFetcher();
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    await cache.get('a'); // populate at t=0
    vi.advanceTimersByTime(MAX_AGE + 200); // t=1200: inside [maxAge, maxAge+swr]

    // Resolves immediately with cached value (no awaiting of the refetch).
    const data = await cache.get('a');
    expect(data).toBe('a:v1'); // old value served
    expect(fetcher.callsTo('a')).toBe(2); // background revalidation fired

    await flushMicrotasks(); // let revalidation settle
    expect(cache.peek('a')).toBe('a:v2'); // entry was updated

    // The refreshed timestamp makes the entry fresh again.
    await cache.get('a');
    expect(fetcher.callsTo('a')).toBe(2); // no additional fetch
  });

  it('stale window: repeated gets fire exactly one background revalidation', async () => {
    const fetcher = makeFetcher();
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    await cache.get('a');
    vi.advanceTimersByTime(MAX_AGE + 100);

    await cache.get('a');
    await cache.get('a');
    await cache.get('a');

    await flushMicrotasks();
    expect(fetcher.callsTo('a')).toBe(2); // one original + exactly one revalidation
  });

  it('expired window: age beyond maxAge + staleWhileRevalidate fetches and awaits new data', async () => {
    const fetcher = makeFetcher();
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    await cache.get('a'); // populate at t=0
    vi.advanceTimersByTime(MAX_AGE + SWR + 1); // t=1501: expired

    const data = await cache.get('a');
    expect(data).toBe('a:v2'); // fresh data awaited, not stale v1
    expect(fetcher.callsTo('a')).toBe(2);

    // New timestamp resets the freshness clock.
    vi.advanceTimersByTime(MAX_AGE - 1);
    await cache.get('a');
    expect(fetcher.callsTo('a')).toBe(2);
  });

  it('window boundaries are respected end to end', async () => {
    const fetcher = makeFetcher();
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    await cache.get('a'); // call 1 at t=0

    vi.advanceTimersByTime(MAX_AGE - 1); // fresh
    await cache.get('a');
    expect(fetcher.callsTo('a')).toBe(1);

    vi.advanceTimersByTime(1); // t=1000 == maxAge -> stale
    await cache.get('a');
    await flushMicrotasks(); // call 2 (background)
    expect(fetcher.callsTo('a')).toBe(2);
    expect(cache.peek('a')).toBe('a:v2');

    vi.advanceTimersByTime(SWR); // t=2000: fetchedAt=1000, age==maxAge+swr -> still stale
    await cache.get('a');
    await flushMicrotasks(); // call 3 (background)
    expect(fetcher.callsTo('a')).toBe(3);
    expect(cache.peek('a')).toBe('a:v3');

    vi.advanceTimersByTime(SWR + 1); // age > maxAge+swr -> expired
    const data = await cache.get('a'); // call 4, awaited
    expect(data).toBe('a:v4');
    expect(fetcher.callsTo('a')).toBe(4);
  });

  it('single-flight: two concurrently awaited gets share one fetch promise', async () => {
    const fetcher = makeFetcher();
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    const [x, y] = await Promise.all([cache.get('k'), cache.get('k')]);

    expect(x).toBe('k:v1');
    expect(y).toBe('k:v1');
    expect(fetcher.callsTo('k')).toBe(1);
  });

  it('single-flight also applies to expired entries and cross-key isolation holds', async () => {
    const fetcher = makeFetcher();
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    await cache.get('a'); // populate 'a' at t=0
    vi.advanceTimersByTime(MAX_AGE + SWR + 100); // both keys expired/missing

    const [a1, a2] = await Promise.all([cache.get('a'), cache.get('a')]);
    const [b1, b2] = await Promise.all([cache.get('b'), cache.get('b')]);

    expect(a1).toBe('a:v2');
    expect(a2).toBe('a:v2');
    expect(fetcher.callsTo('a')).toBe(2);
    expect(b1).toBe('b:v1');
    expect(b2).toBe('b:v1');
    expect(fetcher.callsTo('b')).toBe(1);
  });

  it('failed background revalidation keeps the stale value and schedules nothing weird', async () => {
    // Second call for 'a' rejects; third succeeds.
    const fetcher = makeFetcher({
      a: (n) => {
        if (n === 2) throw new Error('network hiccup');
        return `a:v${n}`;
      },
    });
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    await cache.get('a'); // populate at t=0 (call 1)
    vi.advanceTimersByTime(MAX_AGE + 100); // stale

    // Caller still gets the cached value even though the refetch will fail.
    const data = await cache.get('a');
    expect(data).toBe('a:v1');

    await flushMicrotasks(); // rejection settles in the background
    expect(fetcher.callsTo('a')).toBe(2);
    expect(cache.peek('a')).toBe('a:v1'); // stale value retained, entry untouched

    // The failed attempt released its single-flight slot: a later stale get
    // retries cleanly and succeeds, updating the entry.
    vi.advanceTimersByTime(100); // still within the stale window
    const again = await cache.get('a');
    expect(again).toBe('a:v1'); // still serves cached data immediately
    await flushMicrotasks(); // call 3 succeeds this time
    expect(fetcher.callsTo('a')).toBe(3);
    expect(cache.peek('a')).toBe('a:v3');

    // And the successfully refreshed entry is fresh again: no more calls.
    await cache.get('a');
    expect(fetcher.callsTo('a')).toBe(3);
  });

  it('failed foreground (expired) fetch propagates the error to awaiting callers', async () => {
    const fetcher = makeFetcher({ cold: () => { throw new Error('boom'); } });
    const cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });

    await expect(cache.get('cold')).rejects.toThrow('boom');
    await flushMicrotasks();

    // Slot released: a subsequent get retries.
    await expect(cache.get('cold')).rejects.toThrow('boom');
    expect(fetcher.callsTo('cold')).toBe(2);
  });
});

